head.script:
let objParent = $p.parent();

let cTooltip = "";
let cTooltipDisplay = "";
let cTooltipPositionX = "";
let cTooltipPositionY = "";



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[common > P > tooltipPositionX]<br/>컴포넌트에서 표시할 툴팁의 X 좌표 위치를 설정합니다.",
    "validation" : [
        "툴팁의 X 좌표 위치를 컴포넌트의 width 를 사용한 계산식으로 설정할 수 있어야 합니다.",
        "tooltipDisplay 속성에 의한 툴팁은 계산식으로 설정할 수 없어야 합니다.",
        "값을 설정하지 않으면 tooltipDisplay 속성의 툴팁은 20 으로 적용되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 조건 설정
    cTooltip = con_tooltip.getValue();
    cTooltipDisplay = con_tooltipDisplay.getText();
    cTooltipPositionX = con_tooltipPositionX.getValue();
    cTooltipPositionY = con_tooltipPositionY.getValue();

    // 테스트 샘플에 재생성 조건 값 전달
    objParent.scwin.gVar["cTooltip"] = cTooltip;
    objParent.scwin.gVar["cTooltipDisplay"] = cTooltipDisplay;
    objParent.scwin.gVar["cTooltipPositionX"] = cTooltipPositionX;
    objParent.scwin.gVar["cTooltipPositionY"] = cTooltipPositionY;

    // comp 생성 호출
    await objParent.scwin.comp_init();

    // balloon / tooltipDisplay 툴팁 출현(hover) 시점에 바로 출력하도록 observer 부착
    // (헤드리스에서 클릭 시 scroll/mouseout 으로 툴팁이 숨겨지는 문제 원천 제거)
    scwin.attachTipHoverOutput();
}



// document.body 에 MutationObserver 를 달아 두 종류의 툴팁이 보이는 상태로
// "출현"(숨김→표시) 하는 엣지에 1회만 출력한다.
//  - tooltip 속성 툴팁 : .w2balloonTip (body.js showToolTip)
//  - tooltipDisplay 툴팁 : .w2group_tooltip (xfControl _showTooltip, id = {compId}_tooltip)
// 헤드리스에서 클릭(포커스→scroll→mouseout)이 툴팁을 숨겨 라이브 측정이
// 깨지는 문제를, hover 출현 시 즉시 출력으로 우회한다.
scwin.attachTipHoverOutput = function () {
    if (!objParent.target1) {
        return;
    }

    // 재생성 시 이전 observer 정리
    if (scwin._tipObserver) {
        scwin._tipObserver.disconnect();
        scwin._tipObserver = null;
    }
    scwin.balloonWasVisible = false;
    scwin.displayTipWasVisible = false;

    let emit = function () {
        // ---- tooltip 속성 툴팁 (.w2balloonTip) ----
        let balloon = document.querySelector('.w2balloonTip');
        let balloonLabel = document.querySelector('.w2balloonTip_label');
        let balloonVisible = balloon && balloonLabel && balloonLabel.textContent &&
            window.getComputedStyle(balloon).display !== 'none';

        if (!balloonVisible) {
            scwin.balloonWasVisible = false;
        } else if (!scwin.balloonWasVisible) {
            scwin.balloonWasVisible = true;

            wf_body_bottom.getObj("scwin").setReturnValue("tooltip textContent : " + balloonLabel.textContent);

            // balloon 툴팁의 실측 X 오프셋
            //  - body.js showToolTip : left = getAbsoluteLeft(compEl) + tooltipPositionX
            //    (compEl = 컴포넌트 render 엘리먼트, getAbsoluteLeft 는 문서 기준이라 불변)
            //  - String 계산식("width/2") 은 new Function("width","height", ...)(elemWidth, elemHeight)
            //    으로 평가되어 balloon 툴팁에 그대로 반영된다.
            let compEl = objParent.target1.getElement ? objParent.target1.getElement() : objParent.target1.render;
            if (compEl) {
                let offsetX = Math.round(parseFloat(balloon.style.left) - WebSquare.style.getAbsoluteLeft(compEl));
                wf_body_bottom.getObj("scwin").setReturnValue("tooltip 툴팁 X오프셋(실측): " + offsetX + "px");
            }
        }

        // ---- tooltipDisplay 툴팁 (.w2group_tooltip) ----
        let dispTip = document.querySelector('.w2group_tooltip');
        let dispVisible = dispTip && dispTip.textContent &&
            window.getComputedStyle(dispTip).display !== 'none';

        if (!dispVisible) {
            scwin.displayTipWasVisible = false;
        } else if (!scwin.displayTipWasVisible) {
            scwin.displayTipWasVisible = true;

            wf_body_bottom.getObj("scwin").setReturnValue("tooltipDisplay textContent : " + dispTip.textContent);

            // tooltipDisplay 툴팁의 실측 X 오프셋
            //  - group.js handleMouseoverEvent + xfControl _showTooltip :
            //      left = getAbsoluteLeft(srcElem) + tooltipPositionX (기본 20)
            //  - 계산식은 new Function("cellWidth","cellHeight", ...) 로 평가되어
            //    "width/2" 같은 width 변수 계산식은 ReferenceError → catch → 기본 20 으로 폴백한다.
            //    (= tooltipDisplay 툴팁은 계산식으로 설정 불가)
            //  - srcElem 은 텍스트가 담긴 컴포넌트 render 엘리먼트.
            let srcEl = objParent.target1.getElement ? objParent.target1.getElement() : objParent.target1.render;
            if (srcEl) {
                let offsetX = Math.round(parseFloat(dispTip.style.left) - WebSquare.style.getAbsoluteLeft(srcEl));
                wf_body_bottom.getObj("scwin").setReturnValue("tooltipDisplay 툴팁 X오프셋(실측): " + offsetX + "px");
            }
        }
    };

    scwin._tipObserver = new MutationObserver(emit);
    scwin._tipObserver.observe(document.body, {
        childList: true,
        characterData: true,
        subtree: true,
        attributes: true,
        attributeFilter: ["style", "class"]
    });
}



objParent.scwin.fn_tooltip = function (id, text) {
    return "id - " + id + ", tooltip - " + text;
}



objParent.scwin.target1_onclick = function (id, text) {
    // 출력은 hover(툴팁 출현) 시점에 발생하므로 클릭 핸들러는 비워둔다.
}
